begin;
-- Synthetic fixture explicitly activates Community; production defaults stay closed.
update public.community_operations set enabled=true,enrollment=true,discovery=true,publish=true,engagement=true,cohort_required=false;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values
('c1800000-0000-4000-8000-000000000001','lifecycle-one@mizyun.test'),
('c1800000-0000-4000-8000-000000000002','lifecycle-two@mizyun.test');
update public.profiles set birth_year=1990 where id::text like 'c1800000-%';
set local role authenticated;set local request.jwt.claim.role='authenticated';
set local request.jwt.claim.sub='c1800000-0000-4000-8000-000000000001';
select * from public.community_save_profile('lifecycle_one','Lifecycle One','LO','own bio',true,true,'2026-09-30');
set local request.jwt.claim.sub='c1800000-0000-4000-8000-000000000002';
select * from public.community_save_profile('lifecycle_two','Lifecycle Two','LT','foreign bio',true,true,'2026-09-30');
reset role;set local request.jwt.claim.role='service_role';
insert into public.community_notification_preferences(user_id,muted) values('c1800000-0000-4000-8000-000000000001',true);
insert into public.community_invitations(inviter_user_id,token) select 'c1800000-0000-4000-8000-000000000001', 'private-lifecycle-token-'||n from generate_series(1,3) n;
insert into public.community_reports(reporter_user_id,target_type,target_id,reason,subject_user_id,staff_notes,evidence_snapshot) values
('c1800000-0000-4000-8000-000000000001','profile','c1800000-0000-4000-8000-000000000002','spam','c1800000-0000-4000-8000-000000000002','confidential staff notes','{"secret":"foreign evidence"}');
set local role authenticated;set local request.jwt.claim.role='authenticated';
set local request.jwt.claim.sub='c1800000-0000-4000-8000-000000000001';
select is((select count(*) from public.community_export_page('identity')),1::bigint,'Export scopes identity to caller');
select ok((select bool_and(item->>'handle'='lifecycle_one') from public.community_export_page('identity')),'Export omits foreign identity');
select ok((select bool_and(not item ? 'token') from public.community_export_page('invitations')),'Invitation bearer tokens are excluded');
select ok((select bool_and(not item ? 'staff_notes' and not item ? 'evidence_snapshot' and not item ? 'subject_user_id' and not item ? 'reporter_user_id') from public.community_export_page('reports')),'Report export excludes internal evidence and identifying authority');
select is((select count(*) from public.community_export_page('invitations',null,1)),1::bigint,'Export page is bounded');
select is((select count(*) from public.community_export_page('invitations',(select min(item_key) from public.community_export_page('invitations')),500)),2::bigint,'Export cursor advances without losing remaining rows');
select throws_ok($$select * from public.community_export_page('staff')$$,'P0001','community_conflict','No arbitrary table export');
select throws_ok($$select * from public.community_retention_batch()$$,'42501',null,'Ordinary member cannot run retention erasure');
select throws_ok($$select * from public.community_withdrawal_batch(auth.uid(),1)$$,'42501',null,'Ordinary member cannot run another generation cleanup');
select * from public.community_withdraw_profile();
select throws_ok($$select * from public.community_save_profile('lifecycle_one','Return','RT',null,false,true,'2026-09-30')$$,'P0001','community_conflict','Reenrollment blocked while captured generation cleanup is pending');
reset role;set local request.jwt.claim.role='service_role';
select is((select generation from public.community_withdrawal_jobs where user_id='c1800000-0000-4000-8000-000000000001'),1,'Withdrawal captures original generation');
select is((select complete from public.community_withdrawal_batch('c1800000-0000-4000-8000-000000000001',1,1)),false,'Bounded cleanup leaves resumable work');
select is((select count(*) from public.community_invitations where inviter_user_id='c1800000-0000-4000-8000-000000000001'),2::bigint,'First batch deletes exactly one invitation');
select * from public.community_withdrawal_batch('c1800000-0000-4000-8000-000000000001',1,1);
select is((select complete from public.community_withdrawal_batch('c1800000-0000-4000-8000-000000000001',1,1)),true,'Resumed cleanup completes durable generation');
select is((select muted from public.community_notification_preferences where user_id='c1800000-0000-4000-8000-000000000001'),true,'Withdrawal preserves account-bound notification preferences');
set local role authenticated;set local request.jwt.claim.role='authenticated';
select lives_ok($$select * from public.community_save_profile('lifecycle_one','Return','RT',null,false,true,'2026-09-30')$$,'Fresh enrollment succeeds after cleanup');
reset role;set local request.jwt.claim.role='service_role';
select is((select generation from public.community_profiles where user_id='c1800000-0000-4000-8000-000000000001'),2,'Return has fresh generation');
insert into public.community_invitations(inviter_user_id,token,enrollment_generation) values('c1800000-0000-4000-8000-000000000001','fresh-generation-token',2);
select * from public.community_withdrawal_batch('c1800000-0000-4000-8000-000000000001',1,1);
select is((select count(*) from public.community_invitations where token='fresh-generation-token'),1::bigint,'Old cleanup retry cannot erase a new generation');
select throws_ok($$select * from public.community_account_cleanup_batch('c1800000-0000-4000-8000-000000000001','c1800000-0000-4000-8000-000000000099','stale-worker')$$,'P0001','community_access_denied','Erasure requires matching live deletion lease');
insert into public.community_handle_quarantine(handle,expires_at) values('expired_lifecycle',now()-interval '1 second'),('retained_lifecycle',now()+interval '1 day');
select * from public.community_retention_batch(1);
select is((select count(*) from public.community_handle_quarantine where handle='expired_lifecycle'),0::bigint,'Expiry maintenance purges elapsed quarantine');
select is((select count(*) from public.community_handle_quarantine where handle='retained_lifecycle'),1::bigint,'Maintenance preserves unexpired reservation');
select ok((select retention_expires_at is null from public.community_reports where reporter_user_id='c1800000-0000-4000-8000-000000000001'),'Unresolved necessary case is not silently expired');
update public.community_reports set status='resolved' where reporter_user_id='c1800000-0000-4000-8000-000000000001';
select ok((select retention_expires_at=now()+interval '180 days' from public.community_reports where reporter_user_id='c1800000-0000-4000-8000-000000000001'),'Closing a case starts explicit180-day retention');
-- Active sanctions retain only the minimum appealable case after expiry/erasure.
update public.community_reports set decision='ban',decision_reason='policy breach',assigned_to='independent-staff',retention_expires_at=now()-interval '1 second',notes='old identifiable evidence',staff_notes='old staff quote',evidence_snapshot='{"sensitive":"quote"}' where reporter_user_id='c1800000-0000-4000-8000-000000000001';
insert into public.community_moderation_sanctions(user_id,report_id,kind) select 'c1800000-0000-4000-8000-000000000002',id,'ban' from public.community_reports where reporter_user_id='c1800000-0000-4000-8000-000000000001';
select * from public.community_retention_batch(500);
select is((select count(*) from public.community_reports where subject_user_id='c1800000-0000-4000-8000-000000000002'),1::bigint,'Active permanent sanction keeps minimal appealable case');
select ok((select notes is null and staff_notes is null and evidence_snapshot='{}' from public.community_reports where subject_user_id='c1800000-0000-4000-8000-000000000002'),'Expired sanction-linked case loses all evidence payload');
insert into public.account_deletion_jobs(id,user_id,challenge_hash,status,stage,expires_at,worker_id,lease_expires_at) values('c1800000-0000-4000-8000-000000000099','c1800000-0000-4000-8000-000000000001','synthetic-lifecycle-challenge','in_progress','auth',now()+interval '5 minutes','lifecycle-worker',now()+interval '2 minutes');
select throws_ok($$select * from public.community_account_cleanup_batch('c1800000-0000-4000-8000-000000000001','c1800000-0000-4000-8000-000000000099','old-worker')$$,'P0001','community_access_denied','A stolen/old worker identity cannot erase data');
select * from public.community_account_cleanup_batch('c1800000-0000-4000-8000-000000000001','c1800000-0000-4000-8000-000000000099','lifecycle-worker',500);
select ok((select reporter_user_id is null and notes is null and evidence_snapshot='{}' from public.community_reports where subject_user_id='c1800000-0000-4000-8000-000000000002'),'Reporter erasure retains an anonymized minimal sanction case');
delete from auth.users where id='c1800000-0000-4000-8000-000000000001';
select ok((select report_id is not null from public.community_moderation_sanctions where user_id='c1800000-0000-4000-8000-000000000002'),'Auth cascade does not sever sanction appeal identity');
create temporary table lifecycle_appeal_case as select id from public.community_reports where subject_user_id='c1800000-0000-4000-8000-000000000002';
grant select on lifecycle_appeal_case to authenticated;
set local role authenticated;set local request.jwt.claim.role='authenticated';
set local request.jwt.claim.sub='c1800000-0000-4000-8000-000000000002';
select lives_ok($$select * from public.community_create_moderation_appeal((select id from lifecycle_appeal_case),'Appeal retained sanction')$$,'Sanction remains appealable after reporter Auth erasure');
reset role;set local request.jwt.claim.role='service_role';
select * from finish();
rollback;
